import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Resumen de combate","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/overview.md","filePath":"es/guide/combat/overview.md"}'),n={name:"es/guide/combat/overview.md"};function i(s,a,d,l,c,m){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="combat-overview" tabindex="-1">Resumen de combate <a class="header-anchor" href="#combat-overview" aria-label="Enlace permanente a &quot;Resumen de combate&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto para el marco de acciones · Experimental para los valores numéricos · Aceptado para la separación entre salud y trauma.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Seleccioná un objetivo, gestioná la distancia y elegí compromisos de los que puedas recuperarte.</li><li>Modern y Legacy comparten reglas propuestas; el tiempo, la stamina, el alcance y la información dan forma a las decisiones.</li><li>La salud global y el trauma local siguen siendo fundamentos separados con estado Aceptado; los valores de las acciones tienen estado Experimental.</li></ul><p>Elegí un objetivo, gestioná la distancia y comprometete con acciones de las que puedas recuperarte. Modern y Legacy comparten las reglas de combate propuestas.</p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Qué significa</th></tr></thead><tbody><tr><td>Modern</td><td>Activar cada ataque disponible; dirección experimental preferida</td></tr><tr><td>Legacy</td><td>Cadencia automática; alternativa de diseño compatible</td></tr><tr><td>Acciones</td><td>Acciones básicas del arma, Special Attacks aprendidos y defensas manuales</td></tr><tr><td>Recursos</td><td>La stamina paga el compromiso y la presión repetida</td></tr><tr><td>Posición</td><td>El alcance, la orientación y la recuperación crean oportunidades</td></tr><tr><td>Lesiones</td><td>La salud global y la integridad local son fundamentos separados con estado Aceptado</td></tr></tbody></table><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><ul><li>Seleccioná un objetivo en cualquiera de los modos.</li><li>Usá la distancia y los compromisos legibles para elegir una acción.</li><li>Solicitar una región corporal es un intento, no un resultado garantizado.</li><li>Las defensas potentes necesitan el momento y el enfrentamiento adecuados; no bloquean todo.</li></ul><h2 id="trade-offs" tabindex="-1">Ventajas y costes <a class="header-anchor" href="#trade-offs" aria-label="Enlace permanente a &quot;Ventajas y costes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elección</th><th>Ventaja</th><th>Coste</th></tr></thead><tbody><tr><td>Continuación rápida</td><td>Presión más temprana</td><td>Más stamina y recuperación en el perfil de prueba</td></tr><tr><td>Ritmo paciente</td><td>Acciones sostenibles</td><td>Puede dar tiempo al rival a moverse</td></tr><tr><td>Ataque comprometido</td><td>Mayor amenaza posicional</td><td>Preparación más visible y recuperación que el rival puede castigar</td></tr></tbody></table><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Quien lleva una lanza espera a dos casillas. Quien lleva un martillo puede acercarse, provocar Brace o comprometerse con un ataque pesado visible; el alcance y el momento determinan qué decisión tiene sentido.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/legacy-and-modern.html">Modos</a> · <a href="/Syrolands-Public/es/guide/combat/numeric-prototype.html">Valores de tres armas</a> · <a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Special Attacks</a> · <a href="/Syrolands-Public/es/guide/combat/limbs-and-trauma.html">Extremidades y trauma</a> · <a href="/Syrolands-Public/es/guide/combat/armor-and-protection.html">Armadura</a> · <a href="/Syrolands-Public/es/guide/combat/targeting-and-anatomy.html">Apuntar</a> · <a href="/Syrolands-Public/es/game-design/combat/overview.html">Diseño completo</a></p><p><span id="what-it-is-and-why-it-matters"></span><span id="progression-and-specialization"></span><span id="related-systems"></span><span id="explore-combat"></span></p>',16)])])}const h=e(n,[["render",i]]);export{u as __pageData,h as default};
